<?php
if(PHP_SAPI!=='cli'||!defined('ABSPATH'))exit(2);umask(0077);global $wpdb;$dir=getenv('RF_NATIVE_DIR')?:sys_get_temp_dir().'/rf-native-attribute-plan-'.gmdate('Ymd-His');if(!is_dir($dir))mkdir($dir,0700,true);
$catalog=$wpdb->get_results("SELECT t.term_id,t.name,t.slug,tt.term_taxonomy_id,tt.taxonomy,i.language_code lang,i.trid,i.source_language_code FROM {$wpdb->terms} t JOIN {$wpdb->term_taxonomy} tt USING(term_id) LEFT JOIN {$wpdb->prefix}icl_translations i ON i.element_id=tt.term_taxonomy_id AND i.element_type=CONCAT('tax_',tt.taxonomy) WHERE LEFT(tt.taxonomy,3)='pa_' ORDER BY t.term_id",ARRAY_A);$bySlug=[];$byId=[];$groups=[];foreach($catalog as $t){$bySlug[$t['taxonomy']][$t['slug']][]=$t;$byId[$t['term_id']]=$t;if($t['trid'])$groups[$t['taxonomy']][$t['trid']][$t['lang']][]=$t;}
$products=$wpdb->get_results("SELECT p.ID,p.post_title,p.post_status,p.post_author,i.language_code lang,i.trid FROM {$wpdb->posts} p LEFT JOIN {$wpdb->prefix}icl_translations i ON i.element_id=p.ID AND i.element_type='post_product' WHERE p.post_type='product' AND p.post_status IN ('publish','draft','pending','private','future') AND NOT EXISTS(SELECT 1 FROM {$wpdb->term_relationships} r JOIN {$wpdb->term_taxonomy} tt USING(term_taxonomy_id) JOIN {$wpdb->terms} t USING(term_id) WHERE r.object_id=p.ID AND tt.taxonomy='product_cat' AND (tt.term_id IN (420,421,15052) OR LOWER(t.name) IN ('expired','expirado','expirados','caducado','caducados'))) ORDER BY p.ID",ARRAY_A);
$only=array_filter(array_map('intval',explode(',',getenv('RF_NATIVE_IDS')?:'')));if($only)$products=array_values(array_filter($products,fn($p)=>in_array((int)$p['ID'],$only,true)));
$missing=[];$plans=[];$dates=[];$clean=0;$skipped=[];
foreach($products as $p){$id=(int)$p['ID'];$end=get_post_meta($id,'event_date_end',true);if(preg_match('/^\d{8}$/',(string)$end)&&$end<wp_date('Ymd')){$skipped[]=$id;continue;}$children=$wpdb->get_results($wpdb->prepare("SELECT v.ID,m.meta_id,m.meta_key,m.meta_value FROM {$wpdb->posts} v JOIN {$wpdb->postmeta} m ON m.post_id=v.ID AND LEFT(m.meta_key,13)='attribute_pa_' AND m.meta_value<>'' WHERE v.post_parent=%d AND v.post_type='product_variation' AND v.post_status NOT IN ('trash','auto-draft') ORDER BY v.ID,m.meta_id",$id),ARRAY_A);$rels=$wpdb->get_results($wpdb->prepare("SELECT r.term_taxonomy_id,tt.taxonomy,t.term_id FROM {$wpdb->term_relationships} r JOIN {$wpdb->term_taxonomy} tt USING(term_taxonomy_id) JOIN {$wpdb->terms} t USING(term_id) WHERE r.object_id=%d AND LEFT(tt.taxonomy,3)='pa_'",$id),ARRAY_A);$relIds=array_fill_keys(array_column($rels,'term_taxonomy_id'),true);$issues=[];$wanted=[];$changes=[];
$resolve=function($t,$where)use(&$missing,&$groups,&$p,&$issues){if(!$t||!$p['lang']){$issues[]=['kind'=>'unknown_term_or_product_language','source'=>$t,'where'=>$where];return null;}if($t['lang']===$p['lang'])return $t;$targets=$groups[$t['taxonomy']][$t['trid']][$p['lang']]??[];if(count($targets)===1)return $targets[0];$key=$t['taxonomy'].':'.$t['term_id'].':'.$p['lang'];$missing[$key]=['source'=>$t,'target_lang'=>$p['lang'],'examples'=>array_slice(array_merge($missing[$key]['examples']??[],[$p['ID']]),0,4),'target_count'=>count($targets)];$issues[]=['kind'=>'missing_translation','key'=>$key,'where'=>$where];return null;};
foreach($children as $v){$tax=substr($v['meta_key'],10);$ts=$bySlug[$tax][$v['meta_value']]??[];$t=count($ts)===1?$ts[0]:null;$target=$resolve($t,['variation'=>$v['ID'],'meta_id'=>$v['meta_id']]);if(!$target)continue;$wanted[$tax][$target['term_taxonomy_id']]=$target;if($target['slug']!==$v['meta_value'])$changes[]=['meta_id'=>(int)$v['meta_id'],'post_id'=>(int)$v['ID'],'key'=>$v['meta_key'],'before'=>$v['meta_value'],'after'=>$target['slug'],'source'=>$t,'target'=>$target];if(!$t||$t['lang']!==$p['lang']||!isset($relIds[$t['term_taxonomy_id']]))$issues[]=['kind'=>'variation_language_or_relationship','variation'=>$v['ID']];}
foreach($rels as $r){$t=$byId[$r['term_id']]??null;$target=$resolve($t,['parent_term'=>$r['term_id']]);if($target){$wanted[$r['taxonomy']][$target['term_taxonomy_id']]=$target;if($t['lang']!==$p['lang'])$issues[]=['kind'=>'parent_term_language','term'=>$t['term_id']];}}
$defaults=maybe_unserialize($wpdb->get_var($wpdb->prepare("SELECT meta_value FROM {$wpdb->postmeta} WHERE post_id=%d AND meta_key='_default_attributes' LIMIT 1",$id)));if($defaults===null)$defaults='';$newDefaults=is_array($defaults)?$defaults:[];foreach($newDefaults as $tax=>$slug){if(!str_starts_with($tax,'pa_')||$slug==='')continue;$ts=$bySlug[$tax][$slug]??[];$target=$resolve(count($ts)===1?$ts[0]:null,['default'=>$tax]);if($target){$newDefaults[$tax]=$target['slug'];$wanted[$tax][$target['term_taxonomy_id']]=$target;if($target['slug']!==$slug)$issues[]=['kind'=>'default_language','taxonomy'=>$tax];}}
if(!$issues){$clean++;continue;}$plans[]=['product'=>$p,'end_date'=>$end,'start_date'=>get_post_meta($id,'event_date_start',true),'changes'=>$changes,'wanted_terms'=>$wanted,'defaults_before'=>$defaults,'defaults_after'=>$newDefaults,'issues'=>$issues];}
$r=['site'=>realpath(ABSPATH),'date'=>wp_date('c'),'selected_products'=>count($products),'skipped_ended_by_date'=>count($skipped),'clean_products'=>$clean,'problem_products'=>count($plans),'missing_translation_specs'=>count($missing),'plans'=>$plans,'missing'=>array_values($missing)];file_put_contents($dir.'/plan.json',json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));file_put_contents($dir.'/missing.json',json_encode(array_values($missing),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));echo json_encode(array_diff_key($r,array_flip(['plans','missing'])),JSON_UNESCAPED_UNICODE).PHP_EOL;
